# A small town: travel times in minutes along each road (roads go both ways)
roads = [
    ("Home", "Shop", 2), ("Home", "Park", 4), ("Home", "Library", 13),
    ("Shop", "Park", 1), ("Shop", "Market", 3), ("Park", "Library", 5),
    ("Library", "Market", 4), ("Library", "School", 3), ("Market", "School", 2),
]
graph = {}
for a, b, minutes in roads:
    graph.setdefault(a, {})[b] = minutes
    graph.setdefault(b, {})[a] = minutes

import heapq
from town import graph

def dijkstra(graph, start, goal):
    best = {start: 0}               # fastest known time to each place
    came_from = {}
    queue = [(0, start)]
    settled = []
    while queue:
        time, place = heapq.heappop(queue)     # always expand the closest unsettled place
        if place in settled:
            continue
        settled.append(place)
        if place == goal:
            break
        for nxt, minutes in graph[place].items():
            new_time = time + minutes
            if new_time < best.get(nxt, float("inf")):
                best[nxt] = new_time
                came_from[nxt] = place
                heapq.heappush(queue, (new_time, nxt))
    route = [goal]
    while route[-1] != start:
        route.append(came_from[route[-1]])
    return best[goal], route[::-1], settled

if __name__ == "__main__":
    minutes, route, settled = dijkstra(graph, "Home", "School")
    print("settled in this order:", " -> ".join(settled))
    print(f"fastest route: {' -> '.join(route)} ({minutes} minutes)")

from collections import deque
from town import graph

# Fewest roads (ignoring how long each one takes): breadth-first search
queue, seen = deque([["Home"]]), {"Home"}
while queue:
    path = queue.popleft()
    if path[-1] == "School":
        break
    for nxt in graph[path[-1]]:
        if nxt not in seen:
            seen.add(nxt)
            queue.append(path + [nxt])
minutes = sum(graph[a][b] for a, b in zip(path, path[1:]))
print(f"fewest roads: {' -> '.join(path)} ({len(path) - 1} roads, {minutes} minutes)")

import heapq, random

# A 100 x 100 grid of streets: most blocks take 1 minute, some busy ones take 4
N = 100
rng = random.Random(3)
cost = [[1 if rng.random() < 0.8 else 4 for _ in range(N)] for _ in range(N)]
start, goal = (50, 20), (50, 80)                # across the middle of town

def search(use_estimate):
    best, queue, settled = {start: 0}, [(0, 0, start)], set()
    while queue:
        _, time, (r, c) = heapq.heappop(queue)
        if (r, c) in settled:
            continue
        settled.add((r, c))
        if (r, c) == goal:
            return time, len(settled)
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                t = time + cost[nr][nc]
                if t < best.get((nr, nc), float("inf")):
                    best[(nr, nc)] = t
                    # A*: add a lower bound on the time still to go (every step costs at least 1)
                    guess = (abs(goal[0] - nr) + abs(goal[1] - nc)) if use_estimate else 0
                    heapq.heappush(queue, (t + guess, t, (nr, nc)))

for name, flag in [("Dijkstra", False), ("A*", True)]:
    time, visited = search(flag)
    print(f"{name:<9} fastest time {time} minutes, places settled {visited:,} of {N * N:,}")
